#!/usr/bin/env node
/**
 * Add to the generated iOS project the four things Apple requires and
 * Capacitor's template does not supply.
 *
 * `ios/` is gitignored and regenerated by `pnpm exec cap add ios` on every build, so
 * none of this can be a checked-in file edited by hand — the same
 * regenerate-then-patch shape as patch-android-webview.mjs and verify-ipad.mjs.
 *
 *   1. **NSCameraUsageDescription.** The barcode scanner opens the camera
 *      natively — through ML Kit's own AVFoundation session
 *      (src/components/addfood/barcode/native.ts), not getUserMedia in
 *      WKWebView as the web build still does — but iOS requires this key for
 *      either: any AVCaptureSession, WebView-mediated or not, needs a usage
 *      string. Without one iOS does not merely refuse — it terminates the app
 *      the instant the camera is requested. So the current build crashes on
 *      the first scan, and would crash in front of a reviewer.
 *
 *   2. **CFBundleLocalizations.** The app is translated into 7 languages in
 *      JavaScript, so the bundle carries no .lproj directories and iOS believes
 *      it is English-only — which is what the App Store listing would then
 *      advertise. This key is Apple's documented way for an app that localizes
 *      its own content to declare the languages it actually supports.
 *
 *   3. **PrivacyInfo.xcprivacy.** Required for App Store submission. Declares
 *      what the app collects and which required-reason APIs it calls. Capacitor
 *      core ships its own (empty) manifest for its pod, but a pod's manifest
 *      covers only that pod: the *app's* collection has to be declared by the
 *      app target, and @capacitor/preferences — which is UserDefaults, a
 *      required-reason API — ships no manifest of its own, so its reason has to
 *      be declared here too.
 *
 *   4. **DEVELOPMENT_TEAM.** The template ships `DEVELOPMENT_TEAM = ""` with
 *      automatic signing, which Xcode refuses to build for a device:
 *      "Signing for 'App' requires a development team." CI never hit it — the
 *      unsigned simulator build passes CODE_SIGNING_ALLOWED=NO and the release
 *      archive passes DEVELOPMENT_TEAM on the xcodebuild command line — so the
 *      only path that has ever needed it is the one nobody scripted: opening
 *      the project in Xcode and pressing Run.
 *
 *      Setting it in Xcode does not stick. ios/ is regenerated, so the next
 *      `pnpm run sync:native` hands the empty string back and the error returns
 *      looking like a fresh problem. Hence here, from $APPLE_TEAM_ID — the same
 *      name the release workflow already uses for the same value.
 *
 * Writing the file is not enough for (3): a resource that is not in the target's
 * Resources build phase is not copied into the bundle, and a manifest that isn't
 * in the bundle may as well not exist. So the pbxproj is patched to register it.
 *
 * Run after `pnpm exec cap sync ios`. A no-op with a clear message when ios/ is
 * absent (a Linux CI runner, say), so it can sit unconditionally in the build
 * script and never fail a build. Idempotent: running it twice changes nothing.
 */

import { readFileSync, writeFileSync, existsSync } from 'node:fs'

const ENV_FILE = '.env'
const INFO_PLIST = 'ios/App/App/Info.plist'
const PBXPROJ = 'ios/App/App.xcodeproj/project.pbxproj'
const PRIVACY_MANIFEST = 'ios/App/App/PrivacyInfo.xcprivacy'

/** Kept in sync with LOCALES in src/lib/i18n/index.ts. */
export const LOCALES = ['en', 'it', 'fr', 'es', 'de', 'pt', 'nl']

/**
 * Storefronts the external-purchase link is declared for.
 *
 * Kept in sync with EXTERNAL_PURCHASE_COUNTRIES in
 * src/lib/purchases/externalPurchase.ts — that list decides where the app *shows*
 * the link and this one declares it to Apple, so a disagreement means either a
 * link with no declaration (a rejection) or a declaration for a region the app
 * never uses (harmless but misleading). A test asserts the two match.
 */
export const EXTERNAL_PURCHASE_REGIONS = [
  'US',
  'AT', 'BE', 'BG', 'CY', 'CZ', 'DE', 'DK', 'EE', 'ES', 'FI', 'FR', 'GR', 'HR',
  'HU', 'IE', 'IT', 'LT', 'LU', 'LV', 'MT', 'NL', 'PL', 'PT', 'RO', 'SE', 'SI',
  'SK',
]

/**
 * Why the app wants the camera, in the words the system alert will show.
 *
 * Apple rejects vague usage strings ("this app needs camera access"). This
 * names the feature and the benefit, and — deliberately — the fact that nothing
 * is stored, which is the question the alert actually raises in a user's mind.
 *
 * English only. Localizing a usage string needs InfoPlist.strings in a .lproj
 * per language plus a PBXVariantGroup in the project file; CFBundleLocalizations
 * above covers the listing, and this string is one sentence seen once.
 */
export const CAMERA_USAGE =
  'Etto uses the camera to scan the barcode on a food package so it can ' +
  'look up its nutrition values. Images are read on your device and are never ' +
  'stored or uploaded.'

/**
 * Fixed identifiers for the two objects added to the project file.
 *
 * Xcode's own are 24 hex digits derived from a counter and a timestamp. These
 * keep that shape — some pbxproj tooling validates it — but are constant rather
 * than generated, which is what makes the patch idempotent: a fresh id per run
 * would append a duplicate object on every build. The leading run of A's puts
 * them somewhere Xcode's counter will not reach.
 */
const FILE_REF_ID = 'AAAAAAAA0000000000000C01'
const BUILD_FILE_ID = 'AAAAAAAA0000000000000C02'

// ---------------------------------------------------------------------------
// Info.plist
// ---------------------------------------------------------------------------

/** Whether a top-level key is already declared. */
export function hasPlistKey(plist, key) {
  return new RegExp(`<key>${key}</key>`).test(plist)
}

/**
 * Insert entries before the plist's closing `</dict>`.
 *
 * Anchored on the *last* `</dict>` so a nested dictionary (there are none today,
 * but Capacitor's template has grown keys before) can't attract the insertion
 * into the middle of the file.
 */
export function insertPlistEntries(plist, entries) {
  if (entries.length === 0) return plist
  const marker = plist.lastIndexOf('</dict>')
  if (marker === -1) throw new Error(`${INFO_PLIST}: no closing </dict> found`)
  return plist.slice(0, marker) + entries.join('') + plist.slice(marker)
}

/**
 * `SKExternalPurchaseLink` — the external-purchase link's declaration.
 *
 * Only written when the build opts in via `VITE_EXTERNAL_PURCHASE_LINK`, because
 * the key is inert (and the link illegal) without Apple having granted
 * `com.apple.developer.storekit.external-purchase-link` for the same regions
 * first. Keys are lowercase storefront region codes, one URL each; the app shows
 * the link only on storefronts in `EXTERNAL_PURCHASE_COUNTRIES`
 * (src/lib/purchases/externalPurchase.ts), so the two lists have to agree.
 *
 * **Check both key names against Apple's current documentation before enabling
 * this.** The external-purchase rules are the most-changed corner of the review
 * guidelines, and a declaration that no longer matches what Apple expects fails
 * at signing or, worse, at review.
 */
export function externalPurchaseLinkEntries(url, regions) {
  const items = regions
    .map((r) => `\t\t<key>${r.toLowerCase()}</key>\n\t\t<string>${url}</string>\n`)
    .join('')
  return `\t<key>SKExternalPurchaseLink</key>\n\t<dict>\n${items}\t</dict>\n`
}

export function patchInfoPlist(
  plist,
  { locales = LOCALES, cameraUsage = CAMERA_USAGE, externalPurchase = null } = {},
) {
  const entries = []

  if (!hasPlistKey(plist, 'NSCameraUsageDescription')) {
    entries.push(`\t<key>NSCameraUsageDescription</key>\n\t<string>${cameraUsage}</string>\n`)
  }

  if (!hasPlistKey(plist, 'CFBundleLocalizations')) {
    const items = locales.map((l) => `\t\t<string>${l}</string>\n`).join('')
    entries.push(`\t<key>CFBundleLocalizations</key>\n\t<array>\n${items}\t</array>\n`)
  }

  if (externalPurchase && !hasPlistKey(plist, 'SKExternalPurchaseLink')) {
    entries.push(externalPurchaseLinkEntries(externalPurchase.url, externalPurchase.regions))
  }

  return insertPlistEntries(plist, entries)
}

// ---------------------------------------------------------------------------
// PrivacyInfo.xcprivacy
// ---------------------------------------------------------------------------

/**
 * The app's privacy manifest.
 *
 * Every collected type is declared linked-to-identity and not used for
 * tracking, which is the truth: the data is keyed to an account so it can be
 * read back on another device, and there is no advertising, analytics or
 * attribution SDK in the app at all — hence the empty tracking-domains array
 * and NSPrivacyTracking false.
 *
 * Health covers weight and body measurements; Fitness covers the food and
 * water diary. Apple's taxonomy has no "nutrition" type and puts dietary
 * logging under fitness, so both are declared rather than guessing at one.
 *
 * Two required-reason APIs are declared:
 *
 *   - **UserDefaults**, reached through @capacitor/preferences. Reason CA92.1 is
 *     "access information from the app itself" — the plugin stores this app's own
 *     preferences and reads nothing written by anyone else.
 *   - **File timestamps**, reached through @capacitor/filesystem, which the Pro
 *     data export uses to write the file it hands to the share sheet. Reason
 *     C617.1 is "timestamps of files inside the app container" — the export is
 *     written to this app's own cache directory and nowhere else. Apple's check
 *     is on the binary rather than the call path, so the reason is declared for
 *     the plugin being linked at all, not only for the call the app makes.
 *
 * PurchaseHistory is in the collected list above because Pro exists: RevenueCat
 * is told the Supabase user id so the entitlement can be attached to an account,
 * which makes the purchase linked-to-identity — but never used for tracking,
 * since nothing in the app profiles anyone across apps or hands data to a broker.
 */
export function privacyManifest() {
  const collected = [
    { type: 'NSPrivacyCollectedDataTypeEmailAddress' },
    { type: 'NSPrivacyCollectedDataTypeUserID' },
    { type: 'NSPrivacyCollectedDataTypeHealth' },
    { type: 'NSPrivacyCollectedDataTypeFitness' },
    { type: 'NSPrivacyCollectedDataTypePurchaseHistory' },
  ]

  const entries = collected
    .map(
      ({ type }) => `		<dict>
			<key>NSPrivacyCollectedDataType</key>
			<string>${type}</string>
			<key>NSPrivacyCollectedDataTypeLinked</key>
			<true/>
			<key>NSPrivacyCollectedDataTypeTracking</key>
			<false/>
			<key>NSPrivacyCollectedDataTypePurposes</key>
			<array>
				<string>NSPrivacyCollectedDataTypePurposeAppFunctionality</string>
			</array>
		</dict>
`,
    )
    .join('')

  return `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<!--
	Generated by scripts/patch-ios-project.mjs — ios/ is regenerated on every
	build, so edit the script, not this file.
-->
<plist version="1.0">
<dict>
	<key>NSPrivacyTracking</key>
	<false/>
	<key>NSPrivacyTrackingDomains</key>
	<array/>
	<key>NSPrivacyCollectedDataTypes</key>
	<array>
${entries}	</array>
	<key>NSPrivacyAccessedAPITypes</key>
	<array>
		<dict>
			<key>NSPrivacyAccessedAPIType</key>
			<string>NSPrivacyAccessedAPICategoryUserDefaults</string>
			<key>NSPrivacyAccessedAPITypeReasons</key>
			<array>
				<string>CA92.1</string>
			</array>
		</dict>
		<dict>
			<key>NSPrivacyAccessedAPIType</key>
			<string>NSPrivacyAccessedAPICategoryFileTimestamp</string>
			<key>NSPrivacyAccessedAPITypeReasons</key>
			<array>
				<string>C617.1</string>
			</array>
		</dict>
	</array>
</dict>
</plist>
`
}

// ---------------------------------------------------------------------------
// project.pbxproj
// ---------------------------------------------------------------------------

/**
 * Register PrivacyInfo.xcprivacy as a resource of the App target.
 *
 * Four edits, because that is how a pbxproj represents one file: the reference
 * itself, the build-file wrapper, membership of the App group (so it is visible
 * in Xcode), and membership of the Resources phase (so it is actually copied).
 * Only the last one affects the built product, but a file present in the bundle
 * and invisible in the project is how this ends up silently deleted later.
 */
export function patchPbxproj(pbxproj) {
  if (pbxproj.includes(FILE_REF_ID)) return pbxproj

  let out = pbxproj

  out = out.replace(
    '/* End PBXBuildFile section */',
    `\t\t${BUILD_FILE_ID} /* PrivacyInfo.xcprivacy in Resources */ = {isa = PBXBuildFile; fileRef = ${FILE_REF_ID} /* PrivacyInfo.xcprivacy */; };\n/* End PBXBuildFile section */`,
  )

  out = out.replace(
    '/* End PBXFileReference section */',
    `\t\t${FILE_REF_ID} /* PrivacyInfo.xcprivacy */ = {isa = PBXFileReference; lastKnownFileType = text.plist.xml; path = PrivacyInfo.xcprivacy; sourceTree = "<group>"; };\n/* End PBXFileReference section */`,
  )

  // Matched on the group's name and shape rather than on its generated id, so
  // this survives Capacitor renumbering its template — which is exactly the
  // kind of change that would otherwise no-op silently.
  out = out.replace(
    /(\/\* App \*\/ = \{\s*\n\s*isa = PBXGroup;\s*\n\s*children = \(\n)/,
    `$1\t\t\t\t${FILE_REF_ID} /* PrivacyInfo.xcprivacy */,\n`,
  )

  out = out.replace(
    /(isa = PBXResourcesBuildPhase;[\s\S]*?files = \(\n)/,
    `$1\t\t\t\t${BUILD_FILE_ID} /* PrivacyInfo.xcprivacy in Resources */,\n`,
  )

  return out
}

/**
 * A Team ID is 10 characters of Apple's own alphabet — uppercase letters and
 * digits. Validated rather than pasted through because the value lands
 * unquoted-ish inside a pbxproj: a stray quote or newline from a copy-paste
 * would corrupt the project file, and Xcode's error for *that* says nothing
 * about where it came from. A wrong-but-well-formed id still fails, but it
 * fails in Xcode's signing UI, naming the team it could not find.
 */
export const TEAM_ID_PATTERN = /^[A-Z0-9]{10}$/

/**
 * Point both build configurations at a development team.
 *
 * Matches on any current value rather than specifically on `""`, which is what
 * makes it idempotent *and* lets a changed id take effect: a second run over an
 * already-patched project rewrites the same value, and a new APPLE_TEAM_ID
 * replaces the old one instead of being ignored.
 *
 * Returns the count so the caller can tell "patched both configs" from "the
 * template stopped declaring this key", which would otherwise no-op in silence.
 */
export function patchSigning(pbxproj, teamId) {
  if (!TEAM_ID_PATTERN.test(teamId)) {
    throw new Error(
      `APPLE_TEAM_ID must be 10 uppercase letters or digits — got ${JSON.stringify(teamId)}. ` +
        'Find it at https://developer.apple.com/account under Membership details.',
    )
  }
  let count = 0
  const out = pbxproj.replace(/DEVELOPMENT_TEAM = [^;\n]*;/g, () => {
    count++
    return `DEVELOPMENT_TEAM = ${teamId};`
  })
  return { pbxproj: out, count }
}

/**
 * What is still wrong after patching — the same shape verify-ipad.mjs uses.
 *
 * `teamId` is optional because not having one is a valid state: CI's simulator
 * build is unsigned on purpose, and a contributor without an Apple account
 * should still get a working `sync:native`. It is only checked when one was
 * actually asked for.
 */
export function checkAll(plist, pbxproj, manifestExists, teamId = null) {
  const failures = []
  if (!hasPlistKey(plist, 'NSCameraUsageDescription')) {
    failures.push('Info.plist has no NSCameraUsageDescription — iOS kills the app on first scan.')
  }
  if (!hasPlistKey(plist, 'CFBundleLocalizations')) {
    failures.push('Info.plist has no CFBundleLocalizations — the listing would claim English only.')
  }
  if (!manifestExists) {
    failures.push('PrivacyInfo.xcprivacy was not written.')
  }
  if (!pbxproj.includes('PrivacyInfo.xcprivacy in Resources')) {
    failures.push(
      'PrivacyInfo.xcprivacy is not in the Resources build phase, so it would not be ' +
        'copied into the bundle.',
    )
  }
  // Checked separately from the build phase above: the group insertion matches
  // on a different anchor, so a template change can break one and not the
  // other, and a resource that is invisible in Xcode is one somebody deletes.
  const group = pbxproj.slice(
    pbxproj.indexOf('/* Begin PBXGroup section */'),
    pbxproj.indexOf('/* End PBXGroup section */'),
  )
  if (!group.includes('PrivacyInfo.xcprivacy')) {
    failures.push('PrivacyInfo.xcprivacy is not in the App group, so it is invisible in Xcode.')
  }
  if (teamId !== null && !pbxproj.includes(`DEVELOPMENT_TEAM = ${teamId};`)) {
    failures.push(
      `DEVELOPMENT_TEAM was not set to ${teamId} — Xcode will refuse to sign for a device.`,
    )
  }
  return failures
}

if (process.argv[1] && import.meta.url.endsWith(process.argv[1].split('/').pop())) {
  if (!existsSync(INFO_PLIST) || !existsSync(PBXPROJ)) {
    console.log(
      'patch-ios-project: no ios/ project found, skipping (run `pnpm exec cap sync ios` first).',
    )
    process.exit(0)
  }

  // A team id is machine identity rather than app config, but .env is where
  // this project already keeps local-only values and is gitignored, which is
  // exactly what an account identifier wants. An existing environment variable
  // wins, so CI — which sets APPLE_TEAM_ID from a secret and ships no .env —
  // is unaffected.
  if (existsSync(ENV_FILE)) process.loadEnvFile(ENV_FILE)
  const teamId = process.env.APPLE_TEAM_ID?.trim() || null

  // The external-purchase link is opt-in and off by default, so an ordinary
  // build cannot declare a key for an entitlement Apple has not granted. Same
  // flag the app reads (src/lib/purchases/externalPurchase.ts), and the same URL,
  // built from VITE_SITE_URL here rather than imported — this script is plain
  // Node and cannot load the app's modules.
  const linkFlag = (process.env.VITE_EXTERNAL_PURCHASE_LINK ?? '').trim().toLowerCase()
  const externalPurchase =
    linkFlag === '1' || linkFlag === 'true'
      ? {
          url: `${(process.env.VITE_SITE_URL ?? 'https://etto.fitness').replace(/\/+$/, '')}/?checkout=pro`,
          regions: EXTERNAL_PURCHASE_REGIONS,
        }
      : null

  writeFileSync(INFO_PLIST, patchInfoPlist(readFileSync(INFO_PLIST, 'utf8'), { externalPurchase }))
  writeFileSync(PRIVACY_MANIFEST, privacyManifest())

  let pbxproj = patchPbxproj(readFileSync(PBXPROJ, 'utf8'))
  let signedConfigs = 0
  if (teamId !== null) {
    try {
      ;({ pbxproj, count: signedConfigs } = patchSigning(pbxproj, teamId))
    } catch (e) {
      console.error(`patch-ios-project: ${e.message}`)
      process.exit(1)
    }
  }
  writeFileSync(PBXPROJ, pbxproj)

  const failures = checkAll(
    readFileSync(INFO_PLIST, 'utf8'),
    readFileSync(PBXPROJ, 'utf8'),
    existsSync(PRIVACY_MANIFEST),
    teamId,
  )
  if (failures.length > 0) {
    console.error('patch-ios-project: the patch did not take:\n')
    for (const f of failures) console.error(`  - ${f}`)
    console.error('\nThis usually means a Capacitor upgrade changed the iOS template.')
    process.exit(1)
  }

  console.log(
    'patch-ios-project: camera usage string, 7 localizations and the privacy manifest all OK.',
  )

  // Not a failure. An unsigned simulator build is what CI wants and all a
  // contributor without an Apple account can do — but the error Xcode gives
  // when they then try a device says nothing about this script, so name the
  // variable here, where the omission actually happens.
  if (teamId === null) {
    console.log(
      'patch-ios-project: no APPLE_TEAM_ID set, leaving DEVELOPMENT_TEAM empty. The simulator\n' +
        '  builds fine; running on a device will fail with "Signing for \'App\' requires a\n' +
        '  development team". Add APPLE_TEAM_ID=XXXXXXXXXX to .env to fix it permanently.',
    )
  } else {
    console.log(`patch-ios-project: signing team ${teamId} set on ${signedConfigs} configurations.`)
  }
}
